def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m.group(1),int(m.group(2)),int(m.group(3))
        seg=t[m.end():]
        rows=[r.split() for r in seg.split('\n')]
        if k not in G and len(rows)>=h and all(len(r)==w and all(x.isdigit() for x in r) for r in rows[:h]):
            G[k]=[[int(x) for x in r] for r in rows[:h]]
    return G
