def solve_ring(Gin):
    H,W=len(Gin),len(Gin[0])
    bg=Counter(x for r in Gin for x in r).most_common(1)[0][0]
    shp=[c for c in set(sum(Gin,[])) if c!=bg]
    ringcol=shp[0] if len(shp)==1 else None
    out=[[Gin[i][j] for j in range(W)] for i in range(H)]
    for i in range(H):
        for j in range(W):
            if Gin[i][j]==bg: continue
            # BFS over bg components; check ring condition
            pass
    seen=[[False]*W for _ in range(H)]
    lab=[[-1]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if Gin[i][j]==bg and not seen[i][j]:
                q=deque([(i,j)]); comp=[(i,j)]; seen[i][j]=True; lab[i][j]=len(comp)-1
                while q:
                    y,x=q.popleft()
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and Gin[ny][nx]==bg and not seen[ny][nx]:
                            seen[ny][nx]=True; lab[ny][nx]=len(comp); q.append((ny,nx)); comp.append((ny,nx))
                rs=[a for a,b in comp]; cs=[b for a,b in comp]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                h=r1-r0; w=c1-c0
                # check immediate ring (h,w>=1) using ringcol: all border cells of expanded box must be ringcol
                ok=False
                for dh in range(h+1):
                    for dw in range(w+1):
                        r0d,r1d=r0-dh,r1+dh; c0d,c1d=c0-dw,c1+dw
                        if r0d<0 or r1d>=H-1 or c0d<0 or c1d>=W-1: continue
                        ring=True
                        for a in range(r0d,r1d+1):
                            for b in (c0d,c1d):
                                if Gin[a][b]!=ringcol: ring=False; break
                            if not ring: break
                        if ring:
                            for b in range(c0d,c1d+1):
                                for a in (r0d,r1d):
                                    if Gin[a][b]!=ringcol: ring=False; break
                                if not ring: break
                        if ring: ok=True; break
                    if ok: break
                if ok:
                    for a,b in comp: out[a][b]=4
    return out
