def solve_ring2(Gin):
    H,W=len(Gin),len(Gin[0])
    cnt=Counter(x for r in Gin for x in r)
    bg=cnt.most_common(1)[0][0]
    out=[[Gin[i][j] for j in range(W)] for i in range(H)]
    for i in range(H):
        for j in range(W):
            if Gin[i][j]!=bg: continue
            q=deque([(i,j)]); comp=[(i,j)]; vis={(i,j)}
            while q:
                y,x=q.popleft()
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<H and 0<=nx<W and Gin[ny][nx]==bg and (ny,nx) not in vis:
                        vis.add((ny,nx)); q.append((ny,nx)); comp.append((ny,nx))
            rs=[a for a,b in comp]; cs=[b for a,b in comp]
            r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
            # try all expansions of the comp bbox by (-d..+d) in each direction; box must be fully non-bg
            filled=False
            for d in range(1,H):
                for D in range(1,W):
                    r0d,r1d=r0-d,r1+d; c0d,c1d=c0-D,c1+D
                    if r0d<0 or r1d>=H or c0d<0 or c1d>=W: continue
                    ok=True
                    for a in range(r0d,r1d+1):
                        for b in range(c0d,c1d+1):
                            if Gin[a][b]!=bg and (a,b) not in vis:
                                ok=False; break
                        if not ok: break
                    if ok:
                        # ensure comp strictly inside and doesn't overlap walls? require ringcol contiguous loop: all perimeter cells of box are non-bg AND box bigger than comp
                        per_ok=True
                        for a in range(r0d,r1d+1):
                            for b in (c0d,c1d):
                                if Gin[a][b]==bg: per_ok=False; break
                            if not per_ok: break
                        if per_ok:
                            for b in range(c0d,c1d+1):
                                for a in (r0d,r1d):
                                    if Gin[a][b]==bg: per_ok=False; break
                                if not per_ok: break
                        if per_ok and (r1d-r0d)>=2 and (c1d-c0d)>=2:
                            filled=True; break
                if filled: break
            if filled:
                for a,b in comp: out[a][b]=4
    return out
